			}
			else if (tile.ConstBin == 6)
			{
				transform.transform.eulerAngles = new Vector3(0f, 270f, 0f);
			}
			else if (tile.ConstBin == 9)
			{
				transform.transform.eulerAngles = new Vector3(0f, 90f, 0f);
			}
		}
		else if (tile.shape == TileShape.Single)
		{
			transform = Object.Instantiate<Transform>(this.ventTPre, tile.transform);
			if (tile.ConstBin == 1)
			{
				transform.transform.eulerAngles = new Vector3(0f, 180f, 0f);
			}
			else if (tile.ConstBin == 2)
			{
				transform.transform.eulerAngles = new Vector3(0f, 270f, 0f);
