					i--;
				}
			}
			if (list.Count > 0)
			{
				Direction direction = list[cRng.Next(0, list.Count)];
				this.objectsPlaced.Add(builder.InstatiateEnvironmentObject(this.prefab, tilesOfShape[index], direction));
