				tilesOfShape[index].HardCover(this.coverage.Rotated(direction));
			}
			else
			{
				Debug.LogWarning("ObjectPlacer for " + this.prefab.transform.name + " found no eligible directions, so it didn't build.");
			}
			tilesOfShape.RemoveAt(index);
