	private IEnumerator ShutWhenPlayerLeaves(PlayerManager player)
	{
		float num = Vector3.Distance(base.transform.position, player.transform.position);
		float initialPlayerDistance = num;
		while (num < this.maxPlayerDistance || num < initialPlayerDistance + 10f)
		{
			if (Vector3.Distance(base.transform.position, player.transform.position) < this.maxPlayerDistance)
			{
				player.RuleBreak("Lockers", 1f);
			}
			yield return null;
			num = Vector3.Distance(base.transform.position, player.transform.position);
			initialPlayerDistance = Mathf.Min(initialPlayerDistance, num);
		}
		if (this.open)
		{
			this.Toggle();
		}
		yield break;
	}

